use super::BuiltinTool as T;

/// Every builtin tool with the tier it acts at: `reads` changes nothing,
/// `writes` changes files or durable state, `runs` executes commands or code.
/// Approval, plan mode and the capability policy read the tier from here, so
/// a tool is classified once, where it is declared.
pub(super) fn built_in_tools() -> Vec<T> {
    vec![
        T::reads("list_dir", "List a directory under cwd; limit (required) is how many entries to answer; depth recursively includes children that many levels down"),
        T::runs("read", "Unified reader routing local selectors, artifact://, mcp://, HTTP(S), archive entries, SQLite rows, notebooks, documents, and text files"),
        T::reads("read_file", "Read a UTF-8 text file under cwd, whole or the lines a selector names; returns sha256, snapshot path#TAG, visual numbered lines, content; selectors support ranges, comma ranges, raw, and conflicts"),
        T::reads("read_binary_file", "Read one binary file under cwd as base64; maxBytes (required) is how many bytes to send"),
        T::reads("read_image", "Visually inspect a PNG, JPEG, GIF, or WebP image under cwd. Complete image bytes are attached to the next model request; no separate OCR tool is needed. maxBytes (required) is how many bytes to read; an image cut short is refused rather than sent."),
        T::reads("read_archive", "List archive entries or read one entry from .zip, .tar, .tar.gz, or .tgz under cwd as text, binary base64, document text, or image metadata; reading an entry requires maxBytes; text/document entries support line ranges"),
        T::reads("read_document", "Extract readable text from one document under cwd; supports text, HTML, JSON, CSV/TSV, XML/RSS/Atom, notebooks, and basic PDF text streams; supports line ranges; maxBytes (required) is how many bytes of text to answer"),
        T::reads("read_sqlite", "Read a SQLite database under cwd: list tables, inspect a table, fetch one row by primary key, or run a read-only SELECT/WITH query"),
        T::reads("search_text", "Search one file for a literal string and answer every matching line; case-insensitive by default"),
        T::reads("search_files", "Recursively search text files under cwd for a literal string; limit (required) is how many matches to answer; supports path/paths, hidden, gitignore, caseSensitive, and skip; case-insensitive by default"),
        T::reads("glob_paths", "Find files and directories under cwd with simple glob patterns; supports * and ** plus hidden, gitignore, limit (required), and skip"),
        T::reads("grep_regex", "Search text files under cwd with a regular expression; limit (required) is how many matches to answer; supports path/paths, hidden, gitignore, multiline, caseSensitive, and skip; case-insensitive by default"),
        T::writes("write_file", "Create or overwrite a UTF-8 text file under cwd; overwrites require expectedSha256 from read_file; returns sha256 and visual diff; requires --allow-write"),
        T::writes("write", "Unified revision-guarded writer routing normal and notebook files, archive entries, and SQLite row mutations; requires --allow-write"),
        T::writes("write_archive", "Atomically upsert or delete a safe entry in zip/tar archives with expectedSha256 revision guard; requires --allow-write"),
        T::writes("write_sqlite", "Run parameterized insert, update, or delete in an immediate SQLite transaction with expectedSha256 revision guard; requires --allow-write"),
        T::writes("apply_patch", "Apply exact one-occurrence string replacements to an existing UTF-8 file; returns sha256 and visual diff; requires expectedSha256 and --allow-write"),
        T::writes("edit_file", "Apply line-based edits to a UTF-8 file under cwd; returns sha256 and visual diff; requires expectedSha256 and --allow-write"),
        T::writes("edit", "Apply a Jeden anchored visual patch string with [path#TAG], SWAP/DEL/INS/REM/MV and safe block hunks; returns visual diffs; requires --allow-write"),
        T::writes("delete_file", "Delete one UTF-8 file under cwd; returns visual diff; requires expectedSha256 and --allow-write"),
        T::writes("move_file", "Move or rename one file under cwd; returns rename preview; requires expectedSha256 and --allow-write"),
        T::runs("run_command", "Run a shell command in cwd; requires --allow-command; runs until the command ends or the operation is cancelled"),
        T::runs("run_process", "Run one process with argv array in cwd without a shell; requires --allow-command; supports env overrides"),
        T::runs("node_eval", "Run JavaScript with node --input-type=module in cwd; requires --allow-command"),
        T::runs("python_eval", "Run Python code with python3 in cwd; requires --allow-command"),
        T::runs("eval_session", "Evaluate code in a bounded persistent Python or JavaScript kernel; state survives calls and reset starts a clean kernel; requires --allow-command").probe_backed(),
        T::runs("pty_session", "Send input to a persistent bounded pseudo-terminal shell with streamed output, reset, and cancellation; requires --allow-command").probe_backed(),
        T::runs("pty_resize", "Resize a live persistent pseudo-terminal session without spawning a new process; requires --allow-command").probe_backed(),
        T::runs("ast_search", "Run a tree-sitter structural query against Rust, Python, JavaScript, or TypeScript and return captured syntax nodes; limit (required) is how many to answer").probe_backed(),
        T::writes("ast_rewrite", "Preview a tree-sitter captured-node rewrite as a pending action, then atomically apply or discard it; the preview holds until applied or discarded and lands only on the file revision it was made against").probe_backed(),
        T::runs("lsp", "Use an automatically discovered persistent language server for health, diagnostics, definition, references, rename, code actions, or formatting").probe_backed(),
        T::reads("list_package_scripts", "List package.json scripts in cwd"),
        T::runs("run_package_script", "Run one existing package.json script with npm; requires --allow-command or interactive approval; supports env overrides"),
        T::reads("git_status", "Read git status --short for cwd"),
        T::reads("git_diff", "Read git diff for cwd or one path under cwd"),
        T::reads("git_log", "Read recent git commits for cwd or one path under cwd"),
        T::reads("git_show", "Read one git object or commit summary; optional path scopes the output"),
        T::reads("fetch_url", "Fetch one HTTP(S) URL and return text capped at maxBytes with byte count, truncation state, SHA-256, and optional line range"),
        T::reads("fetch_readable_url", "Fetch one HTTP(S) URL and return simplified readable text capped at maxBytes with byte count, truncation state, SHA-256, and optional line range; supports HTML, JSON, CSV/TSV, RSS/Atom/XML, notebooks, and basic PDF text streams"),
        T::writes("save_artifact", "Save UTF-8 content under a name in the current session artifacts directory"),
        T::reads("list_artifacts", "List files in the current session artifact directory"),
        T::reads("read_artifact", "Read one UTF-8 artifact from the current session artifact directory; maxBytes (required) is how many bytes to answer"),
        T::runs("recall_conversation", "Recall a session's conversation: zoom into a line of its chat memory (id and n of `id+n|`, down to a message whole), the date of a message (date=<id>), or the text-only transcript; defaults to the current session, or pass session=<id-or-path>"),
        T::reads("ask_user", "Ask the human user a question during an interactive session; recorded in the operator ask register, and a question already answered in this workspace is answered from it"),
        T::writes("todo", "Manage the current session todo list with init, append, start, done, drop, rm, and view operations; supports phased lists"),
        T::reads("task_evidence", "Read one checksum-validated tool receipt from a Jeden session in this workspace"),
        T::runs("delegate_task", "Run a focused subtask through the bounded durable TaskScheduler and return its typed child-session result"),
        T::writes("memory", "Remember and recall durable scoped notes across Jeden sessions"),
        T::reads("context_recommend", "Recommend what to read for a task from documentation, memory, transcripts and the ground-truth index"),
        T::writes("mcp_list_tools", "List tools from a configured stdio MCP server"),
        T::writes("mcp_call_tool", "Call one tool on a configured stdio MCP server"),
        T::writes("mcp_list_resources", "List resources from a configured stdio MCP server"),
        T::writes("mcp_read_resource", "Read one resource from a configured stdio MCP server"),
        T::writes("mcp_list_prompts", "List prompts from a configured stdio MCP server"),
        T::writes("mcp_get_prompt", "Get one prompt from a configured stdio MCP server"),
    ]
}
